custom_css:
:root {
    --code-bg-dark: rgba(20, 20, 20, 0.98);
    --code-bg-dark-hover: rgba(30, 20, 30, 0.98);
    --code-bg-dark-active: rgba(15, 15, 25, 0.98);
    --code-border: rgba(255, 110, 180, 0.6);
    --code-border-hover: rgba(255, 140, 200, 0.8);
    --code-text: #ff5d9e;
    --code-text-hover: #ff7ab4;
    --code-font: 'Courier New', Courier, monospace;
}

/* 行内代码 */
code {
    background: var(--code-bg-dark);
    color: var(--code-text);
    padding: 0.3em 1em 0.3em 1.3em;
    margin: 0 0.2em;
    border: 1.5px dashed var(--code-border);
    border-radius: 16px 4px 4px 16px !important;
    box-shadow:
        inset 0 0 15px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(0, 0, 0, 0.7);
    font-family: var(--code-font);
    font-weight: 500;
    font-size: 0.95em;
    letter-spacing: 0.03em;
    display: inline-block;
    position: relative;
    transition: all 0.35s cubic-bezier(0.19, 1, 0.22, 1);
    overflow: visible;
}

/* 多行代码块 */
pre code {
    display: block;
    padding: 1.5em;
    margin: 1.5em 0;
    color: #ff73a7;
    background: var(--code-bg-dark);
    border: 1.5px dashed var(--code-border);
    border-radius: 16px 4px 4px 16px;
    line-height: 1.5;
    overflow-x: auto;
    font-family: var(--code-font);
    font-size: 1rem;
    font-weight: 500;
    color: var(--code-text);
    box-shadow:
        inset 0 0 15px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(0, 0, 0, 0.7);
    position: relative;
    counter-reset: line;
    transition: all 0.35s cubic-bezier(0.19, 1, 0.22, 1);
    overflow: visible;
}

/* 右上角图标 */
code::before,
pre code::before {
    content: "";
    position: absolute;
    top: -14px;
    right: -14px;
    width: 28px;
    height: 28px;
    background-image: url("https://sharkpan.xyz/f/mwAvHW/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20%2834%29.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2;
    transform: rotate(5deg);
    transition: transform 0.3s ease;
}

/* 左上角粉色装饰点 */
code::after,
pre code::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 8px;
    width: 6px;
    height: 6px;
    background: #ff5d9e;
    border-radius: 50%;
    transform: translateY(-50%);
    box-shadow:
        0 0 5px #ff5d9e,
        0 0 10px rgba(255, 93, 158, 0.5);
    z-index: 1;
}

/* 悬停效果 */
code:hover,
pre code:hover {
    background: var(--code-bg-dark-hover);
    color: var(--code-text-hover);
    border-color: var(--code-border-hover);
    box-shadow:
        inset 0 0 25px rgba(0, 0, 0, 0.6),
        0 0 0 1px rgba(0, 0, 0, 0.9),
        0 2px 10px rgba(255, 90, 160, 0.3);
    transform: translateY(-1px);
}

code:hover::before,
pre code:hover::before {
    transform: rotate(0deg) scale(1.1);
}

code:active,
pre code:active {
    background: var(--code-bg-dark-active);
    transform: translateY(1px);
}

code:active::before,
pre code:active::before {
    transform: rotate(-5deg) scale(0.95);
}

/* 行号 */
pre code .line::before {
    content: counter(line);
    counter-increment: line;
    display: inline-block;
    width: 2em;
    margin-right: 1.5em;
    margin-left: -0.5em;
    text-align: right;
    color: var(--code-border);
    font-size: 0.9em;
}

/* 语法高亮 */
pre code .keyword { color: var(--code-border); }
pre code .function { color: #8ce6ff; }
pre code .comment { color: #b2b2b2; font-style: italic; }
pre code .string { color: #ffff9d; }
pre code .number { color: #afffaf; }
pre code .operator { color: #ff8e8e; }

/* 响应式优化 */
@media (max-width: 768px) {
    code {
        padding: 0.2em 0.6em;
        font-size: 0.9em;
    }

    pre code {
        padding: 1.2em;
        font-size: 0.95rem;
    }

    code::before,
    pre code::before {
        width: 24px;
        height: 24px;
        top: -12px;
        right: -12px;
    }
}


/* === em样式 === */
em {
    /* 基础样式 */
    font-style: normal;
    padding: 0.3em 1em 0.3em 1.3em;
    margin: 0 0.2em;
    position: relative;
    display: inline-block;
    border-radius: 16px 4px 4px 16px !important;
    overflow: visible; /* 允许子元素溢出 */

    /* 黑粉配色 */
    color: #ff5d9e !important;
    background:
        linear-gradient(145deg,
            rgba(20, 20, 20, 0.98) 0%,
            rgba(25, 15, 25, 0.95) 100%
        );

    /* 虚线边框设计 */
    border: 1.5px dashed rgba(255, 110, 180, 0.6) !important;
    box-shadow:
        inset 0 0 15px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(0, 0, 0, 0.7);

    /* 过渡效果 */
    transition: all 0.35s cubic-bezier(0.19, 1, 0.22, 1);
}

/* 右上角图标（溢出 + 无背景） */
em::before {
    content: "";
    position: absolute;
    top: -14px;
    right: -7px;
    width: 28px;
    height: 28px;
    background-image: url("https://sharkpan.xyz/f/mwAvHW/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20%2834%29.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    /* 移除装饰 */
    background-color: transparent;
    border: none;
    box-shadow: none;
    padding: 0;
    z-index: 2;
    transform: rotate(5deg);
    transition: transform 0.3s ease;
}

/* 左上角装饰点 */
em::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 8px;
    width: 6px;
    height: 6px;
    background: #ff5d9e;
    border-radius: 50%;
    transform: translateY(-50%);
    box-shadow:
        0 0 5px #ff5d9e,
        0 0 10px rgba(255, 93, 158, 0.5);
}

/* 悬停效果 */
em:hover {
    background:
        linear-gradient(145deg,
            rgba(30, 20, 30, 0.98) 0%,
            rgba(35, 15, 25, 0.95) 100%
        );
    color: #ff7ab4 !important;
    border-color: rgba(255, 140, 200, 0.8) !important;
    box-shadow:
        inset 0 0 25px rgba(0, 0, 0, 0.6),
        0 0 0 1px rgba(0, 0, 0, 0.9),
        0 2px 10px rgba(255, 90, 160, 0.3);
    transform: translateY(-1px);
}

em:hover::before {
    transform: rotate(0deg) scale(1.1);
}

/* 活动状态 */
em:active {
    transform: translateY(1px);
    background:
        linear-gradient(145deg,
            rgba(15, 15, 25, 0.98) 0%,
            rgba(20, 10, 20, 0.95) 100%
        );
}

em:active::before {
    transform: rotate(-5deg) scale(0.95);
}

/* 去除阴影 */
.mes_button,
.mes_edit_buttons,
#completion_prompt_manager
#completion_prompt_manager_list
li.completion_prompt_manager_prompt
span
span
span {
filter: none !important;
}

/* 提示词 */
#completion_prompt_manager
.completion_prompt_manager_header_advanced span {
filter: drop-shadow(0px 0px 0px);
}

/* 强制所有禁用状态文字保持原色 - 增强版 */
*:disabled, 
*[disabled], 
*[aria-disabled="true"], 
*[readonly],
.disabled, 
.inactive,
.disabled *,
.inactive * {
    color: inherit !important;
    -webkit-text-fill-color: inherit !important;
    text-fill-color: inherit !important;
    opacity: 1 !important;
    filter: none !important;
}

/* 覆盖所有输入类型 */
input:disabled,
input[disabled],
textarea:disabled,
textarea[disabled],
select:disabled,
select[disabled] {
    color: inherit !important;
    -webkit-text-fill-color: inherit !important;
    text-fill-color: inherit !important;
    -webkit-opacity: 1 !important;
    -moz-opacity: 1 !important;
    opacity: 1 !important;
}

/* 覆盖浏览器默认阴影 */
input:-webkit-autofill,
input:-webkit-autofill:hover, 
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
    -webkit-text-fill-color: inherit !important;
    box-shadow: 0 0 0 1000px transparent inset !important;
}

/* 覆盖所有伪元素 */
::placeholder,
::-webkit-input-placeholder,
::-moz-placeholder,
:-ms-input-placeholder,
input::placeholder,
textarea::placeholder {
    color: inherit !important;
    opacity: 0.7 !important;
}

/* 特殊框架覆盖 */
[class*="disabled"]:not(.keep-style),
[class*="disabled"] *:not(.keep-style),
[class*="is-disabled"]:not(.keep-style),
[class*="is-disabled"] *:not(.keep-style) {
    color: inherit !important;
    opacity: 1 !important;
}

/* 强制光标样式 */
:disabled {
    cursor: not-allowed !important;
}

/* 固定图案颜色 */
.drawer-icon.closedIcon {
    opacity: 0.8;
}

#rightSendForm>div:not(.mes_stop), #leftSendForm>div {
    opacity: 1;
}


/*下拉选择框 */
select {
    /* 像素风背景色 */
    background-color: rgba(20, 20, 20, 0.95) !important;

    /* 多重背景：图标 + 像素条纹 */
    background-image:
        /* URL 图标（替代箭头） */
        url('https://sharkpan.xyz/f/OpXNfy/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20%2858%29.png'),
        /* 像素风条纹 */
        repeating-linear-gradient(
            to bottom,
            rgba(80, 0, 40, 0.3),
            rgba(80, 0, 40, 0.3) 1px,
            transparent 1px,
            transparent 4px
        );
    background-repeat:
        no-repeat, /* 图标 不重复 */
        repeat;    /* 条纹 重复 */
    background-position:
        /* 图标：距离右侧 12px，垂直居中；可根据需要调节“12px” */
        calc(100% - 12px) 50%,
        /* 条纹：从左上角开始铺满 */
        0 0;
    background-size:
        /* 图标 大小：12×12px；可根据需要调节 */
        22px 22px,
        /* 条纹 自动 */
        auto;

    /* 隐藏系统默认箭头 */
    appearance: none !important;
    -moz-appearance: none !important;
    -webkit-appearance: none !important;

    /* 像素风边框 */
    border: 2px solid !important;
    border-radius: 0 !important; /* 直角风格 */
    border-color:
        #ff73a7   /* 上边框 - 亮粉 */
        #d84a81   /* 右边框 - 暗粉 */
        #d84a81   /* 下边框 - 暗粉 */
        #ff73a7   /* 左边框 - 亮粉 */ !important;

    /* 文本样式 */
    color: #ffb6c1 !important; /* 粉白色文字 */
    font-family: 'Courier New', Courier, monospace !important;
    font-weight: bold !important;
    text-shadow: 0 0 3px #ff0080 !important;

    /* 为图标预留空间 */
    padding: 8px 30px 8px 10px !important; /* top/right/bottom/left */

    /* 像素阴影 */
    box-shadow:
        inset 4px 4px 0 rgba(200, 0, 80, 0.3),
        inset -4px -4px 0 rgba(255, 180, 200, 0.2),
        4px 4px 0 rgba(0, 0, 0, 0.25) !important;

    outline: none !important;
    transition: all 0.1s ease !important;
}
}

/* 通用样式 - 黑粉主题 + 虚线装饰 + 立体感背景 */
.mesIDDisplay, 
.tokenCounterDisplay, 
.mes_timer {
  position: relative;
  padding: 12px 45px 12px 45px; /* 顶/右/下/左 内边距 */
  margin: 10px 0;
  background: linear-gradient(145deg, #121212, #000000); /* 深色渐变营造立体感 */
  color: #ff6bce; /* 粉色文字 */
  border: 2px dashed #ff6bce; /* 粉色虚线边框 */
  border-radius: 8px;
  font-family: 'Segoe UI', sans-serif;
  box-shadow:
    /* 外阴影：右下角较深，左上角较浅，形成浮雕效果 */
    4px 4px 8px rgba(0, 0, 0, 0.3),
   -4px -4px 8px rgba(50, 50, 50, 0.2),
    /* 内阴影：营造嵌入效果 */
    inset 2px 2px 5px rgba(0, 0, 0, 0.5),
    inset -2px -2px 5px rgba(60, 60, 60, 0.3);
  min-height: 30px; /* 确保最小高度 */
  box-sizing: border-box;
}

/* 右上角角标 */
.mesIDDisplay::after,
.tokenCounterDisplay::after,
.mes_timer::after {
  content: "";
  position: absolute;
  top: -10px;         /* 与容器顶部保持 5px 间距 */
  right: -7px;       /* 与容器右侧保持 5px 间距 */
  width: 15px;      /* 角标宽度 15px */
  height: 15px;     /* 角标高度 15px */
  background: url('https://sharkpan.xyz/f/a6QViY/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20(11).png') center/contain no-repeat;
  pointer-events: none;
  filter: drop-shadow(0 0 4px rgba(255, 107, 206, 0.8)); /* 微弱辉光 */
}

/* 可爱风格思维链头部容器 - 黑色背景 + 粉色主题 */
.mes_reasoning_header {
  background: rgba(0, 0, 0, 0.5); /* 深紫黑色半透明背景 */
  border: 3px solid transparent; /* 设置透明边框，以便为内置虚线提供空间 */
  border-radius: 5px;
  padding: 10px 42px 10px 10px; /* 右侧增加空间给精灵素材 */
  margin-bottom: 8px;
  color: #FFEBF7;
  box-shadow:
    0 0 10px rgba(255, 158, 207, 0.35),
    0 0 15px rgba(195, 105, 255, 0.25),
    inset 0 0 5px rgba(255, 182, 242, 0.2);
  display: flex;
  align-items: center;
  backdrop-filter: blur(8px);
  position: relative;
  animation: glowPink 5s ease-in-out infinite;
  font-family: 'Comic Sans MS', 'Marker Felt', sans-serif; /* 可爱风格字体 */
  box-sizing: border-box; /* 包括边框和内边距 */
}

/* 内置虚线边框效果 */
.mes_reasoning_header::before {
  content: "";
  position: absolute;
  top: 5px;  /* 距离上边缘 */
  left: 5px;  /* 距离左边缘 */
  right: 5px; /* 距离右边缘 */
  bottom: 5px; /* 距离下边缘 */
  border: 2px dashed #FF9ECF; /* 粉色虚线 */
  border-radius: 5px; /* 与主容器一致的圆角 */
  pointer-events: none; /* 防止阻止主元素的交互 */
}

/* 右上角精灵素材 */
.mes_reasoning_header::after {
  content: "";
  position: absolute;
  top: 0px;
  right: -3px;
  width: 40px;
  height: 40px;
  background: url('https://sharkpan.xyz/f/A5Z3CZ/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20%2819%29.png') center/contain no-repeat;
  filter: drop-shadow(0 0 8px rgba(255, 190, 251, 0.8));
  z-index: 10;
}

/* ===== 标签卡片全局控制系统 ===== */
:root {
  /* 基础定位 */
  --mes-base-y: 45px;     /* 垂直基准位置 */
  --mes-base-x: 40px;    /* 水平基准偏移 */
  --mes-gap:70px;        /* 卡片间距 */
}

/* 公共样式 - 所有卡片共用 */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
  position: absolute;
  top: var(--mes-base-y);
  display: inline-flex;
  align-items: center;
  padding: 4px 12px 4px 8px;
  z-index: 20;
}

/* AI 卡片的右对齐（右对齐的统一规则） */
.mes[is_user='false'] .mesIDDisplay    { right: calc(var(--mes-base-x) + var(--mes-gap) * 0); }
.mes[is_user='false'] .tokenCounterDisplay { right: calc(var(--mes-base-x) + var(--mes-gap) * 1); }
.mes[is_user='false'] .mes_timer       { right: calc(var(--mes-base-x) + var(--mes-gap) * 2); }

/* 用户卡片的左对齐（左对齐的统一规则） */
.mes[is_user='true'] .mesIDDisplay    { left: calc(var(--mes-base-x) + var(--mes-gap) * 0); }
.mes[is_user='true'] .tokenCounterDisplay { left: calc(var(--mes-base-x) + var(--mes-gap) * 1); }
.mes[is_user='true'] .mes_timer       { left: calc(var(--mes-base-x) + var(--mes-gap) * 2); }

:root {
  /* 用户头像装饰 */
  --user-frame: url('https://sharkpan.xyz/f/wgMNuq/%E6%9C%AA%E6%A0%87%E9%A2%98-2.png'); 

  /* 机器人头像装饰 */
  --bot-frame: url('https://sharkpan.xyz/f/MALQCa/%E6%9C%AA%E6%A0%87%E9%A2%98-3.png'); 

  /* 装饰尺寸调节 (原比例140%x190%) */
  --frame-width: 210%;
  --frame-height: 260%;

  /* 装饰位置微调 */
  --frame-offset-x: -35%; /* 保持居中 */
  --frame-offset-y: -45%; /* 保持居中 */
}

/* ===== 头像装饰框实现 ===== */
.mes .mesAvatarWrapper .avatar::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--frame-width);
  height: var(--frame-height);
  transform: translate(var(--frame-offset-x), var(--frame-offset-y));
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain;
  pointer-events: none;
  z-index: 1;
}

/* 用户头像框 */
.mes[is_user='true'] .mesAvatarWrapper .avatar::after {
  background-image: var(--user-frame); /* 应用自定义图片 */
}

/* 机器人头像框 */
.mes[is_user='false'] .mesAvatarWrapper .avatar::after {
  background-image: var(--bot-frame); /* 应用自定义图片 */
}

/* 文字选择效果 */
::selection {
    background: #FF69B4;
    color: white;
    text-shadow: none;
}

/* 气泡容器定位 */
#chat .mes_block {
    position: relative !important; /* 关键定位基准 */
    padding-top: 65px !important; /* 为头像预留空间 */
    margin-top: 25px !important; /* 增加上边距避免重叠 */
}

/* 头像定位系统 */
.mes[is_user='false'] .avatar {
    position: absolute !important;
    top: 5px !important; /* 上移超出气泡 */
    left: 12% !important; /* 机器人头像移到左侧 */
    transform: translateX(-50%) !important; /* 水平居中 */
    z-index: 10 !important; /* 确保显示在装饰元素上方 */
}

.mes[is_user='true'] .avatar {
    position: absolute !important;
    top: 5px !important; /* 上移超出气泡 */
    right: 15% !important; /* 用户头像移到右侧 */
    transform: translateX(50%) !important; /* 水平居中 */
    z-index: 10 !important; /* 确保显示在装饰元素上方 */
}

/* 头像视觉样式 */
.mes .avatar img {
    width: 80px !important;  /* 固定尺寸 */
    height: 80px !important;
}

/* 粉色渐变气泡核心样式 */
.mes_block {
    position: relative; /* 确保伪元素定位正确 */
    background: linear-gradient(145deg, 
        rgba(255, 192, 203, 1) 20%,   /* 粉红色 */
        rgba(255, 105, 180, 1) 80%     /* 玫红色 */
    ) !important;
    border-radius: 25px !important;
    margin: 15px 1% !important;
    padding: 20px 20px !important;
    box-shadow: 0 5px 25px rgba(255, 182, 193, 0.3) !important;
}

/* 黑色内虚线框系统 */
.mes_block::before {
    content: "";
    position: absolute;
    top: 6px;
    left: 6px;
    right: 6px;
    bottom: 6px;
    border: 2px dashed rgba(0, 0, 0, 1); /* 黑色虚线 */
    border-radius: 15px; /* 主气泡25px - 间距5px */
    box-shadow: 
        inset 0 0 12px rgba(0, 0, 0, 0.1),  /* 黑色内发光 */
        0 0 8px rgba(0, 0, 0, 0.15);       /* 黑色外投影 */
    z-index: 1;
    pointer-events: none;
}

/* AI消息黑色边框增强 */
.mes:not([is_user="true"]) .mes_block::before,
.mes:not([is_user="false"]) .mes_block::before {
    border-width: 2.5px;
    opacity: 0.6;
}

/* 移动端适配 */
@media (max-width: 768px) {
    .mes_block::before {
        top: 4px;
        left: 4px;
        right: 4px;
        bottom: 4px;
        border-width: 1.8px;
        border-radius: 18px;
    }

    .mes_time {
        font-size: 0.75em;
        padding: 3px 10px !important;
    }
}

/* 用户消息特别样式 */
.mes[is_user="true"] .mes_block {
    background: linear-gradient(45deg,
        rgba(255, 192, 203, 1),  /* 粉红 */
        rgba(255, 105, 180, 1)    /* 玫红 */
    ) !important;
