/* 黑粉搭配控件 - 自定义图标版 */
input[type="checkbox"]:checked,
input[type="radio"]:checked {
    position: relative;
    background-color: #2a001a !important;  /* 深紫黑背景 */
    border-color: #ff73a7 !important;      /* 粉红边框 */
}

/* 隐藏默认对勾 */
input[type="checkbox"]:checked::before,
input[type="radio"]:checked::before {
    content: "" !important;
}

/* 添加图标 */
input[type="checkbox"]:checked::after,
input[type="radio"]:checked::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 14px;
    height: 14px;
    background-image: url('https://sharkpan.xyz/f/mwAvHW/%E7%81%B5%E5%8A%A8%E7%B4%A0%E6%9D%90%E5%BA%97%20%2834%29.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    image-rendering: pixelated;
}

/* 调整单选框图标位置微调 */
input[type="radio"]:checked::after {
    margin-top: -1px;
}

/* 焦点高亮 */
input[type="checkbox"]:focus,
input[type="radio"]:focus {
    box-shadow: 0 0 0 2px rgba(255, 105, 160, 0.4) !important;
}

/* 黑粉控件未选中状态样式 */
input[type="checkbox"],
input[type="radio"] {
    appearance: none; /* 移除默认样式 */
    width: 16px;
    height: 16px;
    background-color: #000000 !important; /* 黑色底 */
    border: 1px solid #ff73a7 !important; /* 粉色边框 */
    border-radius: 2px; /* 可调圆角，单选框改为50% */
    cursor: pointer;
    position: relative;
    vertical-align: middle;
    image-rendering: pixelated;
    transition: all 0.1s ease-in-out;
}

/* 单选框为圆形 */
input[type="radio"] {
    border-radius: 50%;
}


