        height: 2px;
        background: #ff73a7;
        border-radius: 0;
        box-shadow: none;
    }

    &::-moz-range-track {
        height: 2px;
        background: #1a1a1a;
        border: 0;
    }

    /* 焦点状态增强 */
    &:focus {
        outline: none;

        &::-webkit-slider-runnable-track {
            box-shadow: 0 0 0 2px rgba(0,0,0,0.1);
